targetScope = 'resourceGroup'

@description('Nom de la Container App qui reçoit le rôle.')
param containerAppName string

@description('Object ID du principal auquel le rôle est attribué.')
param principalId string

@description('ID de définition du rôle intégré.')
param roleDefinitionId string

var containerAppsContributorRoleId = '{{role:Container Apps Contributor}}'

resource ordersApi '{{resource:ContainerApp}}' existing = {
  name: containerAppName
}

resource appDeliveryContainerAppsContributor 'Microsoft.Authorization/roleAssignments@{{roleAssignmentApiVersion}}' = {
  name: guid(ordersApi.id, principalId, containerAppsContributorRoleId)
  scope: ordersApi
  properties: {
    roleDefinitionId: roleDefinitionId
    principalId: principalId
    principalType: 'ServicePrincipal'
  }
}

